<?php
require_once __DIR__ . '/../includes/functions.php'; require_role(['admin']); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$role=$_POST['role']??'cashier';$verified=isset($_POST['is_verified'])?1:0;$active=isset($_POST['is_active'])?1:0;if(!in_array($role,['admin','staff','cashier'],true))$error='Invalid role.';elseif($id===(int)current_user()['id']&&$role!=='admin')$error='You cannot remove your own administrator role.';else{$s=$conn->prepare('UPDATE users SET role=?,is_verified=?,is_active=? WHERE id=?');$s->bind_param('siii',$role,$verified,$active,$id);$s->execute();log_activity($conn,'UPDATE','users',$id,'Role/account status updated');flash('success','User updated.');redirect('admin/users.php');}}
layout_header('User accounts');
?>
<div class="alert alert-info">Public registration can only create cashier accounts. Use this page to assign roles. Only verified and active accounts can log in.</div><section class="card"><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Verified</th><th>Active</th><th>Save changes</th></tr></thead><tbody><?php $q=$conn->query('SELECT id,name,email,role,is_verified,is_active FROM users ORDER BY created_at DESC');while($u=$q->fetch_assoc()): ?><tr><form method="post"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $u['id'] ?>"><td><?= e($u['name']) ?></td><td><?= e($u['email']) ?></td><td><select name="role"><?php foreach(['admin','staff','cashier'] as $r): ?><option value="<?= $r ?>" <?= $u['role']===$r?'selected':'' ?>><?= ucfirst($r) ?></option><?php endforeach; ?></select></td><td><input type="checkbox" name="is_verified" <?= $u['is_verified']?'checked':'' ?>></td><td><input type="checkbox" name="is_active" <?= $u['is_active']?'checked':'' ?>></td><td><button class="btn btn-small">Update</button></td></form></tr><?php endwhile; ?></tbody></table></div></section>
<?php layout_footer(); ?>
